<?php require_once __DIR__.'/functions.php';require_once __DIR__.'/app_init.php';require_role('Propietario');$pdo=dogvive_db();$uid=dogvive_user_id();$q=$pdo->prepare('SELECT * FROM mascota WHERE id_usuario=? ORDER BY id_mascota DESC LIMIT 4');$q->execute([$uid]);$pets=$q->fetchAll();$q=$pdo->prepare("SELECT COUNT(*) FROM reserva WHERE id_usuario=? AND Estado IN ('Pendiente','Confirmada') AND Fecha>=CURDATE()");$q->execute([$uid]);$upcoming=(int)$q->fetchColumn();$q=$pdo->query("SELECT COUNT(*) FROM usuario WHERE LOWER(Tipo_usuario)='entrenador'");$trainerCount=(int)$q->fetchColumn();$q=$pdo->prepare("SELECT COUNT(*) FROM notificacion WHERE id_usuario=? AND Estado<>'Leida'");$q->execute([$uid]);$unread=(int)$q->fetchColumn();$q=$pdo->prepare("SELECT r.*,s.Nombre AS servicio,m.Nombre AS mascota,t.Nombre AS entrenador,t.Apellido AS entrenador_apellido FROM reserva r LEFT JOIN servicio s ON s.id_servicio=r.id_servicio LEFT JOIN mascota m ON m.id_mascota=r.id_mascota LEFT JOIN usuario t ON t.id_usuario=r.id_entrenador WHERE r.id_usuario=? AND r.Estado IN ('Pendiente','Confirmada') ORDER BY r.Fecha,r.Hora LIMIT 1");$q->execute([$uid]);$next=$q->fetch();start_app('Inicio','dashboard');page_wrap_start('Hola, '.(string)($_SESSION['dogvibe_user']['nombre']??'').' 👋','Tu espacio para cuidar y entrenar a tus mascotas.'); ?>
<div class="grid grid-4"><a class="card stat-card" href="<?= e(page_url('mascotas')) ?>"><div class="stat-icon">🐾</div><strong><?= count($pets) ?></strong><small>Mis mascotas visibles</small></a><a class="card stat-card" href="<?= e(page_url('reservas')) ?>"><div class="stat-icon">📅</div><strong><?= $upcoming ?></strong><small>Sesiones próximas</small></a><a class="card stat-card" href="<?= e(page_url('entrenadores')) ?>"><div class="stat-icon">🎓</div><strong><?= $trainerCount ?></strong><small>Entrenadores registrados</small></a><a class="card stat-card" href="<?= e(page_url('notificaciones')) ?>"><div class="stat-icon">🔔</div><strong><?= $unread ?></strong><small>Sin leer</small></a></div><div style="margin:22px 0"><?= btn('🔍 Buscar entrenador',page_url('entrenadores')) ?> <?= btn('＋ Registrar mascota',page_url('registro-mascota'),'btn-secondary') ?></div><div class="grid grid-2"><div><h2 class="section-title">Mis mascotas</h2><?php if(!$pets): ?><div class="card"><p>Aún no has registrado mascotas.</p><?= btn('Registrar primera mascota',page_url('registro-mascota'),'btn-primary') ?></div><?php else: foreach($pets as $pet): ?><div class="card pet-row"><?php if($pet['Foto']): ?><img src="<?= e(base_url().'/'.$pet['Foto']) ?>" alt="<?= e($pet['Nombre']) ?>"><?php else: ?><div class="avatar avatar-small">🐾</div><?php endif; ?><div class="grow"><strong><?= e($pet['Nombre']) ?></strong><small class="muted"><?= e($pet['Raza']??'Raza no indicada') ?> · <?= (int)$pet['Edad'] ?> años</small></div><?= btn('Ver →',base_url().'/mascota-perfil.php?id='.(int)$pet['id_mascota'],'btn-secondary') ?></div><?php endforeach;endif; ?></div><div><h2 class="section-title">Próxima sesión</h2><div class="card session-card"><?php if(!$next): ?><p>No tienes sesiones próximas.</p><?= btn('Solicitar servicio',page_url('solicitud-servicio'),'btn-primary full') ?><?php else: ?><div class="trainer-mini"><div class="grow"><strong><?= e((string)$next['servicio']) ?></strong><small class="muted"><?= e((string)$next['entrenador']?trim($next['entrenador'].' '.$next['entrenador_apellido']):'Entrenador por asignar') ?></small></div><span class="badge orange"><?= e((string)$next['Estado']) ?></span></div><div class="grid grid-3" style="margin-top:20px"><div><small class="muted">Mascota</small><strong><?= e((string)$next['mascota']) ?></strong></div><div><small class="muted">Fecha</small><strong><?= e((string)$next['Fecha']) ?></strong></div><div><small class="muted">Hora</small><strong><?= e(substr((string)$next['Hora'],0,5)) ?></strong></div></div><?= btn('Ver reserva',page_url('reservas'),'btn-secondary full') ?><?php endif; ?></div><h2 class="section-title">Accesos rápidos</h2><div class="card"><?= btn('💬 Mensajes',page_url('mensajes'),'btn-secondary full') ?><?= btn('📈 Seguimiento',page_url('seguimiento'),'btn-secondary full') ?><?= btn('📩 Soporte PQRSD',page_url('pqrsd'),'btn-secondary full') ?></div></div></div><?php page_wrap_end();end_app();
